-- Скрипт создания структуры базы данных «Гараж» (PostgreSQL)
-- Вариант 1: выполнить вручную (psql или pgAdmin) один раз перед первым запуском.
-- Вариант 2: вместо этого скрипта можно сгенерировать миграции EF Core командой:
--   dotnet ef migrations add InitialCreate
--   dotnet ef database update
-- Структура таблиц в обоих случаях совпадает.

CREATE TABLE IF NOT EXISTS "Cars" (
    "Id"           integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Make"         character varying(50)  NOT NULL,
    "Model"        character varying(50)  NOT NULL,
    "Year"         integer                NOT NULL
                 CONSTRAINT "CK_Cars_Year" CHECK ("Year" BETWEEN 1900 AND 2100),
    "Vin"          character varying(17)  NOT NULL,
    "Mileage"      integer                NOT NULL DEFAULT 0
                 CONSTRAINT "CK_Cars_Mileage" CHECK ("Mileage" >= 0),
    "Status"       character varying(20)  NOT NULL DEFAULT 'OnTheRoad',
    "Drivetrain"   character varying(20)  NOT NULL DEFAULT 'Front',
    "FuelType"     character varying(20)  NOT NULL DEFAULT 'Petrol',
    "EngineVolume" real                   NULL,
    "PowerHp"      integer                NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS "IX_Cars_Vin" ON "Cars" ("Vin");

CREATE TABLE IF NOT EXISTS "ServiceRecords" (
    "Id"       integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "CarId"    integer                NOT NULL REFERENCES "Cars" ("Id") ON DELETE CASCADE,
    "WorkType" character varying(100) NOT NULL,
    "Date"     date                   NOT NULL,
    "Mileage"  integer                NOT NULL DEFAULT 0
             CONSTRAINT "CK_ServiceRecords_Mileage" CHECK ("Mileage" >= 0),
    "Cost"     numeric(18,2)          NOT NULL
             CONSTRAINT "CK_ServiceRecords_Cost" CHECK ("Cost" >= 0),
    "Notes"    character varying(500) NULL
);

CREATE INDEX IF NOT EXISTS "IX_ServiceRecords_CarId" ON "ServiceRecords" ("CarId");

CREATE TABLE IF NOT EXISTS "CarPhotos" (
    "Id"         integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "CarId"      integer                NOT NULL REFERENCES "Cars" ("Id") ON DELETE CASCADE,
    "FileName"   character varying(255) NOT NULL,
    "UploadedAt" timestamp with time zone NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS "IX_CarPhotos_FileName" ON "CarPhotos" ("FileName");
CREATE INDEX IF NOT EXISTS "IX_CarPhotos_CarId" ON "CarPhotos" ("CarId");
